import { onINP, onLCP } from 'web-vitals';

function reportVitals() {
  onINP((metric) => {
    fetch('/rum', { method: 'POST', body: JSON.stringify({ inp: metric.value }) });
  });
  onLCP((metric) => {
    fetch('/rum', { method: 'POST', body: JSON.stringify({ lcp: metric.value }) });
  });
}

